from copy import deepcopy
import re
import unicodedata


class DocumentIndex:
    def __init__(self):
        self._by_code = {}
        self._handles = set()
        self._order = []

    @staticmethod
    def _base_handle(title):
        ascii_title = unicodedata.normalize("NFKD", title).encode("ascii", "ignore").decode("ascii")
        return re.sub(r"[^a-z0-9]+", "-", ascii_title.lower()).strip("-") or "document"

    def add(self, title, code, notes=None):
        if not isinstance(title, str) or not title:
            raise ValueError("title must be a non-empty string")
        if not isinstance(code, str) or not code or re.fullmatch(r"[A-Za-z0-9_-]+", code) is None:
            raise ValueError("code has an invalid format")
        if code in self._by_code and self._by_code[code]["title"] != title:
            raise ValueError("code already exists")
        if notes is not None and not isinstance(notes, dict):
            raise TypeError("notes must be a dictionary or None")

        base = self._base_handle(title)
        handle = base
        if handle in self._handles:
            handle = f"{base}-{code}"

        record = {
            "title": title,
            "code": code,
            "handle": handle,
            "notes": deepcopy(notes) if notes is not None else {},
        }
        self._by_code[code] = record
        self._handles.add(handle)
        self._order.append(code)
        return deepcopy(record)

    def link(self, code):
        if code not in self._by_code:
            raise KeyError(code)
        return f"https://archive.invalid/items/{code}"

    def entries(self):
        return [deepcopy(self._by_code[code]) for code in self._order]

